    response = send(workspace_id, {"settings": values, "require_receipt": True})
    if not response.get("ok"):
        raise RuntimeError("Settings save failed")
    # The provider receipt ships in a later increment. When the provider returns an
    # `applied` receipt, it must confirm the save was applied. A provider that does not
    # yet send the receipt omits the key entirely; that legacy response stays a success
    # so the client keeps working against the current provider (independent delivery).
    if "applied" in response and not response["applied"]:
        raise RuntimeError("Settings reported saved but not applied")
    return {"saved": True, "enhanced": enhanced_settings}

